@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {


  List<List<int>> graph = [
    [0, 16, 13, 0, 0, 0],
    [0, 0, 10, 12, 0, 0],
    [0, 4, 0, 0, 14, 0],
    [0, 0, 9, 0, 0, 20],
    [0, 0, 0, 7, 0, 4],
    [0, 0, 0, 0, 0, 0],
  ];

  int source = 0;
  int sink = 5;
  int n = graph.length;

  int fordFulkerson(List<List<int>> graph, int s, int t) {

    List<List<int>> residual = [
      for (var row in graph) [...row]
    ];
    List<int> parent = List.filled(n, -1);
    int maxFlow = 0;

    bool bfs(List<List<int>> rGraph, int s, int t, List<int> parent) {
      List<bool> visited = List.filled(n, false);
      Queue<int> queue = Queue<int>();
      queue.add(s);
      visited[s] = true;
      parent[s] = -1;

      while (queue.isNotEmpty) {
        int u = queue.removeFirst();
        for (int v = 0; v < n; v++) {
          if (!visited[v] && rGraph[u][v] > 0) {
            queue.add(v);
            parent[v] = u;
            visited[v] = true;
            if (v == t) return true;
          }
        }
      }
      return false;
    }

    while (bfs(residual, s, t, parent)) {

      int pathFlow = 1 << 30;
      int v = t;
      while (v != s) {
        int u = parent[v];
        pathFlow = pathFlow < residual[u][v] ? pathFlow : residual[u][v];
        v = u;
      }

      v = t;
      while (v != s) {
        int u = parent[v];
        residual[u][v] -= pathFlow;
        residual[v][u] += pathFlow;
        v = u;
      }

      maxFlow += pathFlow;
    }
    return maxFlow;
  }

  int result = fordFulkerson(graph, source, sink);
  print('The maximum possible flow is $result');
}

import 'dart:io';
import 'dart:math';

class Point {
  final int x, y;
  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';
}

int cross(Point o, Point a, Point b) {
  return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}

int dist2(Point a, Point b) {
  int dx = a.x - b.x, dy = a.y - b.y;
  return dx * dx + dy * dy;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  List<Point> points = [
    Point(0, 3),
    Point(2, 2),
    Point(1, 1),
    Point(2, 1),
    Point(3, 0),
    Point(0, 0),
    Point(3, 3),
  ];

  if (points.length <= 1) {
    print('Convex hull: $points');
    return;
  }

  points.sort((a, b) {
    if (a.y != b.y) return a.y - b.y;
    return a.x - b.x;
  });
  Point p0 = points[0];

  points = [p0] +
      points.sublist(1)
        ..sort((a, b) {
          int cp = cross(p0, a, b);
          if (cp == 0) {

            return dist2(p0, a) - dist2(p0, b);
          }
          return -cp; 
        });

  List<Point> hull = [];
  for (var p in points) {
    while (hull.length >= 2 &&
        cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  print('Convex hull:');
  for (var p in hull) {
    print(p);
  }
}

