import 'dart:math';

class Point {
  final double x;
  final double y;

  Point(this.x, this.y);
}

double distance(Point p1, Point p2) {
  return sqrt(pow(p1.x - p2.x, 2) + pow(p1.y - p2.y, 2));
}

double bruteForceClosest(List<Point> points) {
  double minDist = double.infinity;
  for (int i = 0; i < points.length; i++) {
    for (int j = i + 1; j < points.length; j++) {
      double dist = distance(points[i], points[j]);
      if (dist < minDist) minDist = dist;
    }
  }
  return minDist;
}

double stripClosest(List<Point> strip, double delta) {
  double minDist = delta;
  strip.sort((a, b) => a.y.compareTo(b.y)); 

  for (int i = 0; i < strip.length; i++) {
    for (int j = i + 1; j < strip.length && (strip[j].y - strip[i].y) < minDist; j++) {
      double dist = distance(strip[i], strip[j]);
      if (dist < minDist) minDist = dist;
    }
  }
  return minDist;
}

double closestUtil(List<Point> pointsX, List<Point> pointsY) {
  if (pointsX.length <= 3) {
    return bruteForceClosest(pointsX);
  }

  int mid = pointsX.length ~/ 2;
  Point midPoint = pointsX[mid];

  List<Point> leftX = pointsX.sublist(0, mid);
  List<Point> rightX = pointsX.sublist(mid);

  List<Point> leftY = [];
  List<Point> rightY = [];
  for (var p in pointsY) {
    if (p.x <= midPoint.x) {
      leftY.add(p);
    } else {
      rightY.add(p);
    }
  }

  double dl = closestUtil(leftX, leftY);
  double dr = closestUtil(rightX, rightY);
  double delta = min(dl, dr);

  List<Point> strip = [];
  for (var p in pointsY) {
    if ((p.x - midPoint.x).abs() < delta) {
      strip.add(p);
    }
  }

  return min(delta, stripClosest(strip, delta));
}

double closestPair(List<Point> points) {
  List<Point> pointsX = List.from(points)..sort((a, b) => a.x.compareTo(b.x));
  List<Point> pointsY = List.from(points)..sort((a, b) => a.y.compareTo(b.y));
  return closestUtil(pointsX, pointsY);
}

