@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  List<List<double>> points = [
    [3, 6],
    [17, 15],
    [13, 15],
    [6, 12],
    [9, 1],
    [2, 7],
    [10, 19],
  ];

  const int k = 2;

  Node? buildKdTree(List<List<double>> pts, int depth) {
    if (pts.isEmpty) return null;

    int axis = depth % k;

    pts.sort((a, b) => a[axis].compareTo(b[axis]));

    int medianIndex = pts.length ~/ 2;

    Node node = Node(pts[medianIndex]);

    node.left = buildKdTree(pts.sublist(0, medianIndex), depth + 1);
    node.right = buildKdTree(pts.sublist(medianIndex + 1), depth + 1);

    return node;
  }

  Node? root = buildKdTree(points, 0);

  void printTree(Node? node, int depth) {
    if (node == null) return;
    printTree(node.left, depth + 1);
    print('Depth $depth: ${node.point}');
    printTree(node.right, depth + 1);
  }

  print('Constructed k-d tree:');
  printTree(root, 0);
}

