void validateProfile(Map<String, dynamic> profile) {
  List<String> issues = [];

  if (profile['username'] == null || profile['username'].isEmpty) {
    issues.add('Username is required');
  }

  if (profile['email'] == null || !isValidEmail(profile['email'])) {
    issues.add('Valid email is required');
  }

  if (profile['displayName'] == null || profile['displayName'].isEmpty) {
    issues.add('Display name is required');
  }

  if (profile['username'] != null && !isValidUsername(profile['username'])) {
    issues.add('Username must contain only letters, numbers, and underscores');
  }

  if (profile['bio'] != null && profile['bio'].length > 200) {
    issues.add('Bio must be 200 characters or less');
  }

  if (issues.isEmpty) {
    print('✓ Profile validation passed!');
  } else {
    print('✗ Profile validation failed:');
    issues.forEach((issue) => print('  - $issue'));
  }
}

bool isValidEmail(String email) {
  final emailRegex = RegExp(r'^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$');
  return emailRegex.hasMatch(email);
}

bool isValidUsername(String username) {
  final usernameRegex = RegExp(r'^[a-zA-Z0-9_]+$');
  return usernameRegex.hasMatch(username);
}

