@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate(List<String> args) {



  final Map<String, Map<String, double>> ratings = {
    'User1': {'ItemA': 5, 'ItemB': 3, 'ItemC': 2},
    'User2': {'ItemA': 4, 'ItemB': 2, 'ItemD': 3},
    'User3': {'ItemA': 2, 'ItemC': 5, 'ItemD': 3},
    'User4': {'ItemB': 5, 'ItemC': 3},
    'User5': {'ItemA': 4, 'ItemB': 4, 'ItemC': 1, 'ItemD': 5},
  };



  if (args.isEmpty) {
    print('Usage: dart collaborative_filtering.dart <UserName>');
    print('Known users: ${ratings.keys.join(', ')}');
    return;
  }
  final String targetUser = args.first;
  if (!ratings.containsKey(targetUser)) {
    print('Unknown user: $targetUser');
    return;
  }



  double cosineSimilarity(
    Map<String, double> u,
    Map<String, double> v,
  ) {
    final commonItems =
        u.keys.where((item) => v.containsKey(item)).toList(growable: false);
    if (commonItems.isEmpty) return 0.0;

    double dot = 0, normU = 0, normV = 0;
    for (final item in commonItems) {
      dot += u[item]! * v[item]!;
    }
    for (final r in u.values) normU += r * r;
    for (final r in v.values) normV += r * r;
    if (normU == 0 || normV == 0) return 0.0;
    return dot / (sqrt(normU) * sqrt(normV));
  }



  final Map<String, double> similarities = {};
  ratings.forEach((otherUser, otherRatings) {
    if (otherUser == targetUser) return;
    similarities[otherUser] =
        cosineSimilarity(ratings[targetUser]!, otherRatings);
  });



  final predicted = <String, double>{};
  final targetItems = ratings[targetUser]!.keys;

  final allItems = <String>{
    for (final m in ratings.values) ...m.keys,
  };

  for (final item in allItems) {
    if (targetItems.contains(item)) continue; 

    double num = 0; 
    double den = 0; 
    ratings.forEach((otherUser, otherRatings) {
      if (!otherRatings.containsKey(item)) return;
      final sim = similarities[otherUser] ?? 0.0;
      if (sim == 0) return;
      num += sim * otherRatings[item]!;
      den += sim.abs();
    });
    if (den != 0) predicted[item] = num / den;
  }



  if (predicted.isEmpty) {
    print('No unseen items to recommend for $targetUser.');
    return;
  }

  final sorted = predicted.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));

  print('Recommendations for $targetUser (highest → lowest):');
  for (final e in sorted) {
    print('  ${e.key.padRight(6)}  predicted rating: ${e.value.toStringAsFixed(3)}');
  }
}

