import 'dart:math' as math;

/// Immutable representation of a rational number.
class Fraction {
  /// The fraction's numerator.
  final int numerator;

  /// The fraction's denominator (always positive and non-zero).
  final int denominator;

  const Fraction._internal(this.numerator, this.denominator);

  /// Public constructor that normalises `numerator/denominator`.
  factory Fraction(int numerator, int denominator) {
    if (denominator == 0) {
      throw ArgumentError('Denominator cannot be zero.');
    }

    if (denominator < 0) {
      numerator = -numerator;
      denominator = -denominator;
    }

    final g = _gcd(numerator, denominator);
    return Fraction._internal(numerator ~/ g, denominator ~/ g);
  }

  /// Greatest common divisor (Euclidean algorithm).
  static int _gcd(int a, int b) {
    a = a.abs();
    b = b.abs();
    while (b != 0) {
      final temp = b;
      b = a % b;
      a = temp;
    }

    return a == 0 ? 1 : a;
  }

  Fraction operator +(Fraction other) => Fraction(
        numerator * other.denominator + other.numerator * denominator,
        denominator * other.denominator,
      );

  Fraction operator -(Fraction other) => Fraction(
        numerator * other.denominator - other.numerator * denominator,
        denominator * other.denominator,
      );

  Fraction operator *(Fraction other) =>
      Fraction(numerator * other.numerator, denominator * other.denominator);

  Fraction operator /(Fraction other) =>
      Fraction(numerator * other.denominator, denominator * other.numerator);

  Fraction operator -() => Fraction(-numerator, denominator);

  @override
  bool operator ==(Object other) =>
      other is Fraction &&
      numerator == other.numerator &&
      denominator == other.denominator;

  @override
  int get hashCode => numerator.hashCode ^ denominator.hashCode;

  @override
  String toString() =>
      denominator == 1 ? '$numerator' : '$numerator/$denominator';
}

