import 'dart:math' as math;

class Complex {
  /// Real part
  final double re;

  /// Imaginary part
  final double im;

  const Complex(this.re, [this.im = 0]);

  Complex operator +(Object other) {
    if (other is Complex) return Complex(re + other.re, im + other.im);
    final d = (other as num).toDouble();
    return Complex(re + d, im);
  }

  Complex operator -(Object other) {
    if (other is Complex) return Complex(re - other.re, im - other.im);
    final d = (other as num).toDouble();
    return Complex(re - d, im);
  }

  Complex operator -() => Complex(-re, -im);

  Complex operator *(Object other) {
    if (other is Complex) {
      return Complex(
        re * other.re - im * other.im,
        re * other.im + im * other.re,
      );
    }
    final d = (other as num).toDouble();
    return Complex(re * d, im * d);
  }

  Complex operator /(Object other) {
    if (other is Complex) {
      final denom = other.re * other.re + other.im * other.im;
      return Complex(
        (re * other.re + im * other.im) / denom,
        (im * other.re - re * other.im) / denom,
      );
    }
    final d = (other as num).toDouble();
    return Complex(re / d, im / d);
  }

  Complex get conjugate => Complex(re, -im);

  double get magnitude => math.sqrt(re * re + im * im);

  double get argument => math.atan2(im, re);

  /// e^(a+bi) = e^a (cos b + i sin b)
  Complex exp() {
    final expRe = math.exp(re);
    return Complex(expRe * math.cos(im), expRe * math.sin(im));
  }

  /// Create a complex number from its polar representation
  factory Complex.fromPolar(double r, double theta) =>
      Complex(r * math.cos(theta), r * math.sin(theta));

  @override
  String toString() {
    if (im == 0) return re.toString();
    if (re == 0) return '${im}i';
    final sign = im >= 0 ? '+' : '-';
    return '$re $sign ${im.abs()}i';
  }
}

