@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  final cities = [
    [0, 0],   
    [1, 5],   
    [5, 6],   
    [6, 1],   
    [8, 3],   
  ];

  final n = cities.length;

  double distance(List<int> city1, List<int> city2) {
    final dx = city1[0] - city2[0];
    final dy = city1[1] - city2[1];
    return (dx * dx + dy * dy).toDouble();
  }

  double calculateRouteDistance(List<int> route, List<List<int>> cities) {
    double totalDistance = 0;
    for (int i = 0; i < route.length - 1; i++) {
      totalDistance += distance(cities[route[i]], cities[route[i + 1]]);
    }

    totalDistance += distance(cities[route[route.length - 1]], cities[route[0]]);
    return totalDistance;
  }

  void generatePermutations(List<int> arr, int size, List<List<int>> result) {
    if (size == 1) {
      result.add(List.from(arr));
      return;
    }

    for (int i = 0; i < size; i++) {
      generatePermutations(arr, size - 1, result);

      if (size % 2 == 1) {

        final temp = arr[0];
        arr[0] = arr[size - 1];
        arr[size - 1] = temp;
      } else {

        final temp = arr[i];
        arr[i] = arr[size - 1];
        arr[size - 1] = temp;
      }
    }
  }

  final initialRoute = List.generate(n, (i) => i);
  final allPermutations = <List<int>>[];

  generatePermutations(initialRoute, n, allPermutations);

  double minDistance = double.infinity;
  List<int>? bestRoute;

  for (final route in allPermutations) {
    final dist = calculateRouteDistance(route, cities);
    if (dist < minDistance) {
      minDistance = dist;
      bestRoute = List.from(route);
    }
  }

  print('Traveling Salesman Problem - Brute Force Solution');
  print('=' * 50);
  print('Number of cities: $n');
  print('Cities coordinates:');
  for (int i = 0; i < cities.length; i++) {
    print('  City ${String.fromCharCode(65 + i)}: (${cities[i][0]}, ${cities[i][1]})');
  }
  print('\nTotal permutations checked: ${allPermutations.length}');
  print('\nBest route found:');

  if (bestRoute != null) {
    final routeNames = bestRoute.map((i) => String.fromCharCode(65 + i)).toList();
    print('  ${routeNames.join(' -> ')} -> ${routeNames[0]}');
    print('  Indices: ${bestRoute.join(' -> ')} -> ${bestRoute[0]}');
    print('\nRoute distances:');
    for (int i = 0; i < bestRoute.length; i++) {
      final from = bestRoute[i];
      final to = bestRoute[(i + 1) % bestRoute.length];
      final dist = distance(cities[from], cities[to]);
      print('  ${String.fromCharCode(65 + from)} -> ${String.fromCharCode(65 + to)}: ${dist.toStringAsFixed(2)}');
    }
    print('\nTotal distance: ${minDistance.toStringAsFixed(2)}');
  } else {
    print('No route found!');
  }
}

