    ['bread', 'butter'],
    ['beer', 'salsa'],
    ['milk', 'bread', 'cheese'],
    ['beer', 'chips', 'salsa'],
  ];

  double minSupport = 0.3; 
  double minConfidence = 0.6; 

  print('Transactions:');
  for (int i = 0; i < transactions.length; i++) {
    print('T${i + 1}: ${transactions[i]}');
  }
  print('\nMinimum Support: ${(minSupport * 100).toStringAsFixed(0)}%');
  print('Minimum Confidence: ${(minConfidence * 100).toStringAsFixed(0)}%\n');

  Map<Set<String>, int> itemCounts = {};
  for (var transaction in transactions) {
    for (var item in transaction) {
      Set<String> itemSet = {item};
      itemCounts[itemSet] = (itemCounts[itemSet] ?? 0) + 1;
    }
  }

  Map<Set<String>, double> frequentItemsets = {};
  Map<Set<String>, double> currentFrequent = {};

  for (var entry in itemCounts.entries) {
    double support = entry.value / transactions.length;
    if (support >= minSupport) {
      currentFrequent[entry.key] = support;
      frequentItemsets[entry.key] = support;
    }
  }

  print('Frequent 1-itemsets:');
  for (var entry in currentFrequent.entries) {
    print('  ${entry.key.toList()}: Support = ${(entry.value * 100).toStringAsFixed(1)}%');
  }

  int k = 2;
  while (currentFrequent.isNotEmpty) {
    print('\nGenerating ${k}-itemsets...');

    Map<Set<String>, int> candidateCounts = {};
    List<Set<String>> frequentList = currentFrequent.keys.toList();

    for (int i = 0; i < frequentList.length; i++) {
      for (int j = i + 1; j < frequentList.length; j++) {
        Set<String> union = {...frequentList[i], ...frequentList[j]};
        if (union.length == k) {

          bool allSubsetsFrequent = true;
          List<String> unionList = union.toList();

          for (int idx = 0; idx < unionList.length; idx++) {
            Set<String> subset = {...unionList};
            subset.remove(unionList[idx]);
            if (!currentFrequent.containsKey(subset) && k > 2) {
              bool found = false;
              for (var freq in frequentItemsets.keys) {
                if (freq.length == subset.length && 
                    freq.containsAll(subset) && 
                    subset.containsAll(freq)) {
                  found = true;
                  break;
                }
              }
              if (!found) {
                allSubsetsFrequent = false;
                break;
              }
            }
          }

          if (allSubsetsFrequent) {
            candidateCounts[union] = 0;
          }
        }
      }
    }

    for (var transaction in transactions) {
      Set<String> transactionSet = transaction.toSet();
      for (var candidate in candidateCounts.keys) {
        if (candidate.every((item) => transactionSet.contains(item))) {
          candidateCounts[candidate] = candidateCounts[candidate]! + 1;
        }
      }
    }

    currentFrequent.clear();
    for (var entry in candidateCounts.entries) {
      double support = entry.value / transactions.length;
      if (support >= minSupport) {
        currentFrequent[entry.key] = support;
        frequentItemsets[entry.key] = support;
      }
    }

    if (currentFrequent.isNotEmpty) {
      print('Frequent ${k}-itemsets:');
      for (var entry in currentFrequent.entries) {
        List<String> items = entry.key.toList()..sort();
        print('  ${items}: Support = ${(entry.value * 100).toStringAsFixed(1)}%');
      }
    } else {
      print('No frequent ${k}-itemsets found.');
    }

    k++;
  }

  print('\n' + '=' * 50);
  print('ASSOCIATION RULES:');
  print('=' * 50);

  List<Map<String, dynamic>> rules = [];

  for (var itemset in frequentItemsets.keys) {
    if (itemset.length >= 2) {
      List<String> items = itemset.toList();

      for (int i = 1; i < (1 << items.length) - 1; i++) {
        Set<String> antecedent = {};
        Set<String> consequent = {};

        for (int j = 0; j < items.length; j++) {
          if ((i & (1 << j)) != 0) {
            antecedent.add(items[j]);
          } else {
            consequent.add(items[j]);
          }
        }

        if (antecedent.isNotEmpty && consequent.isNotEmpty) {

          double itemsetSupport = frequentItemsets[itemset]!;
          double antecedentSupport = 0;

          for (var freq in frequentItemsets.entries) {
            if (freq.key.length == antecedent.length &&
                freq.key.containsAll(antecedent) &&
                antecedent.containsAll(freq.key)) {
              antecedentSupport = freq.value;
              break;
            }
          }

          if (antecedentSupport > 0) {
            double confidence = itemsetSupport / antecedentSupport;

            if (confidence >= minConfidence) {
              double lift = confidence / (frequentItemsets[consequent] ?? 1.0);

              rules.add({
                'antecedent': antecedent.toList()..sort(),
                'consequent': consequent.toList()..sort(),
                'support': itemsetSupport,
                'confidence': confidence,
                'lift': lift,
              });
            }
          }
        }
      }
    }
  }

  rules.sort((a, b) => b['confidence'].compareTo(a['confidence']));

  if (rules.isEmpty) {
    print('No association rules found with the given thresholds.');
  } else {
    print('\nFound ${rules.length} association rules:\n');
    for (var rule in rules) {
      print('${rule['antecedent']} => ${rule['consequent']}');
      print('  Support: ${(rule['support'] * 100).toStringAsFixed(1)}%');
      print('  Confidence: ${(rule['confidence'] * 100).toStringAsFixed(1)}%');
      print('  Lift: ${rule['lift'].toStringAsFixed(2)}');
      print('');
    }
  }

  print('=' * 50);
  print('SUMMARY:');
  print('=' * 50);
  print('Total transactions: ${transactions.length}');
  print('Total frequent itemsets: ${frequentItemsets.length}');
  print('Total association rules: ${rules.length}');

  if (rules.isNotEmpty) {
    var strongestRule = rules.first;
    print('\nStrongest rule (by confidence):');
    print('${strongestRule['antecedent']} => ${strongestRule['consequent']}');
    print('Confidence: ${(strongestRule['confidence'] * 100).toStringAsFixed(1)}%');
  }
}

