sealed class Result<T, E> {
  const Result();

  factory Result.success(T value) => Success(value);
  factory Result.failure(E error) => Failure(error);
}

class Success<T, E> extends Result<T, E> {
  final T value;
  const Success(this.value);
}

class Failure<T, E> extends Result<T, E> {
  final E error;
  const Failure(this.error);
}

sealed class Option<T> {
  const Option();

  factory Option.some(T value) => Some(value);
  factory Option.none() => None();

  Option<R> map<R>(R Function(T) mapper) {
    return switch (this) {
      Some<T>(value: var val) => Option.some(mapper(val)),
      None<T>() => None<R>(),
    };
  }

  Option<R> flatMap<R>(Option<R> Function(T) mapper) {
    return switch (this) {
      Some<T>(value: var val) => mapper(val),
      None<T>() => None<R>(),
    };
  }

  @override
  String toString() {
    return switch (this) {
      Some<T>(value: var val) => 'Some($val)',
      None<T>() => 'None',
    };
  }
}

class Some<T> extends Option<T> {
  final T value;
  const Some(this.value);
}

class None<T> extends Option<T> {
  const None();
}

sealed class Either<L, R> {
  const Either();

  factory Either.left(L value) => Left(value);
  factory Either.right(R value) => Right(value);

  T fold<T>(T Function(L) leftMapper, T Function(R) rightMapper) {
    return switch (this) {
      Left<L, R>(value: var val) => leftMapper(val),
      Right<L, R>(value: var val) => rightMapper(val),
    };
  }
}

class Left<L, R> extends Either<L, R> {
  final L value;
  const Left(this.value);
}

class Right<L, R> extends Either<L, R> {
  final R value;
  const Right(this.value);
}

sealed class State<T, U, V> {
  const State();

  factory State.loading(T message, U progress) => Loading(message, progress);
  factory State.ready(T data, U count, V success) => Ready(data, count, success);
  factory State.error(T error, U code, V recoverable) => Error(error, code, recoverable);
}

class Loading<T, U, V> extends State<T, U, V> {
  final T message;
  final U progress;
  const Loading(this.message, this.progress);
}

class Ready<T, U, V> extends State<T, U, V> {
  final T data;
  final U count;
  final V success;
  const Ready(this.data, this.count, this.success);
}

class Error<T, U, V> extends State<T, U, V> {
  final T error;
  final U code;
  final V recoverable;
  const Error(this.error, this.code, this.recoverable);
}

