void candidate(List<String> args) {

  if (args.length < 2) {
    print('Usage: dart run <script.dart> <text> <pattern>');
    return;
  }

  String text = args[0];
  String pattern = args[1];
  int n = text.length;
  int m = pattern.length;

  if (m > n) {
    print('Pattern length is greater than text length. No match.');
    return;
  }

  const int base = 256;                
  const int mod = 1000000007;          

  int highMul = 1;
  for (int i = 0; i < m - 1; i++) {
    highMul = (highMul * base) % mod;
  }

  int hashPattern = 0;
  int hashWindow = 0;
  for (int i = 0; i < m; i++) {
    hashPattern = (hashPattern * base + pattern.codeUnitAt(i)) % mod;
    hashWindow  = (hashWindow  * base + text.codeUnitAt(i))    % mod;
  }

  List<int> matches = [];

  for (int i = 0; i <= n - m; i++) {

    if (hashPattern == hashWindow) {
      if (text.substring(i, i + m) == pattern) {
        matches.add(i);
      }
    }

    if (i < n - m) {
      int leading = (text.codeUnitAt(i) * highMul) % mod;
      hashWindow = (hashWindow - leading) % mod;
      if (hashWindow < 0) hashWindow += mod;
      hashWindow = (hashWindow * base + text.codeUnitAt(i + m)) % mod;
    }
  }

  if (matches.isEmpty) {
    print('Pattern not found.');
  } else {
    print('Pattern found at positions: $matches');
  }
}

