@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  final graph = <List<int>>[
    [1],       
    [2, 4, 5], 
    [3, 6],    
    [2, 7],    
    [0, 5],    
    [6],       
    [5],       
    [3, 6],    
  ];

  final int n = graph.length;
  final indices = List<int>.filled(n, -1);   
  final lowlink = List<int>.filled(n, 0);    
  final onStack = List<bool>.filled(n, false);
  final stack = <int>[];
  final sccs = <List<int>>[];
  var indexCounter = 0;

  void strongConnect(int v) {
    indices[v] = indexCounter;
    lowlink[v] = indexCounter;
    indexCounter++;
    stack.add(v);
    onStack[v] = true;

    for (final w in graph[v]) {
      if (indices[w] == -1) {

        strongConnect(w);
        lowlink[v] = lowlink[v] < lowlink[w] ? lowlink[v] : lowlink[w];
      } else if (onStack[w]) {

        lowlink[v] = lowlink[v] < indices[w] ? lowlink[v] : indices[w];
      }
    }

    if (lowlink[v] == indices[v]) {
      final scc = <int>[];
      int w;
      do {
        w = stack.removeLast();
        onStack[w] = false;
        scc.add(w);
      } while (w != v);
      sccs.add(scc);
    }
  }

  for (var v = 0; v < n; v++) {
    if (indices[v] == -1) {
      strongConnect(v);
    }
  }

  print('Strongly Connected Components:');
  for (var component in sccs) {
    print(component);
  }
}

