bool candidate(int cycleDays, List<int> intervals, List<int> offsets, int maintenanceStart, int maintenanceEnd) {
  if (intervals.length != offsets.length) return false;
  if (cycleDays <= 0) return false;
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  bool inMaintenance(int day) {
    if (maintenanceStart == -1) return false;
    if (maintenanceStart <= maintenanceEnd) {
      return day >= maintenanceStart && day <= maintenanceEnd;
    } else {
      return day >= maintenanceStart || day <= maintenanceEnd;
    }
  }
  List<int> restockCounts = List<int>.filled(cycleDays, 0);
  for (int i = 0; i < intervals.length; i++) {
    int interval = intervals[i];
    int offset = offsets[i];
    if (interval <= 0) return false;
    offset = offset % cycleDays;
    if (offset < 0) offset += cycleDays;
    int g = gcd(interval, cycleDays);
    int steps = cycleDays ~/ g;
    int day = offset;
    for (int k = 0; k < steps; k++) {
      if (inMaintenance(day)) return false;
      restockCounts[day]++;
      if (restockCounts[day] > 1) return false;
      day = (day + interval) % cycleDays;
    }
  }
  return true;
}

