bool candidate(List<String> logs, int minSize, int minErrors, int maxJitter) {
  final n = logs.length;
  if (n < minSize || minSize <= 0) return false;

  final values = List<int>.filled(n, 0);
  final errPrefix = List<int>.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    final parts = logs[i].split(' ');
    values[i] = int.parse(parts[0]);
    final isErr = parts[1] == 'ERR';
    errPrefix[i + 1] = errPrefix[i] + (isErr ? 1 : 0);
  }

  final adjDiff = List<int>.filled(n - 1, 0);
  for (int i = 0; i < n - 1; i++) {
    final d = values[i + 1] - values[i];
    adjDiff[i] = d < 0 ? -d : d;
  }

  final deque = <int>[];
  int left = 0;

  for (int right = 0; right < n; right++) {
    if (right > 0) {
      final idx = right - 1;
      while (deque.isNotEmpty && adjDiff[deque.last] <= adjDiff[idx]) {
        deque.removeLast();
      }
      deque.add(idx);
    }

    while (deque.isNotEmpty && adjDiff[deque.first] > maxJitter) {
      left = deque.first + 1;
      while (deque.isNotEmpty && deque.first < left) {
        deque.removeAt(0);
      }
    }

    final len = right - left + 1;
    final errors = errPrefix[right + 1] - errPrefix[left];
    if (len >= minSize && errors >= minErrors) {
      return true;
    }
  }

  return false;
}

