bool candidate(List<int> arrivals, List<int> departures, int platforms, int minGap) {
  if (arrivals.length != departures.length) return false;
  if (platforms <= 0) return arrivals.isEmpty;
  if (arrivals.isEmpty) return true;
  final events = <List<int>>[];
  for (var i = 0; i < arrivals.length; i++) {
    final a = arrivals[i];
    final d = departures[i];
    if (a < 0 || d < 0) return false;
    if (d <= a) return false;
    events.add([a, 1]);
    events.add([d + minGap, -1]);
  }
  events.sort((x, y) {
    if (x[0] != y[0]) return x[0] - y[0];
    return x[1] - y[1];
  });
  var current = 0;
  var maxConcurrent = 0;
  for (final e in events) {
    current += e[1];
    if (current > maxConcurrent) maxConcurrent = current;
  }
  return maxConcurrent <= platforms;
}

