double candidate(List<String> rows, int windowSize) {
  if (rows.isEmpty || windowSize <= 0 || rows.length < 2 * windowSize) {
    return -1.0;
  }

  int n = rows.length;
  List<double> densities = [];
  int currentHashes = 0;
  int currentChars = 0;

  for (int i = 0; i < n; i++) {
    int hashes = 0;
    for (int j = 0; j < rows[i].length; j++) {
      if (rows[i][j] == '#') hashes++;
    }

    currentHashes += hashes;
    currentChars += rows[i].length;

    if (i >= windowSize) {
      int prevHashes = 0;
      for (int j = 0; j < rows[i - windowSize].length; j++) {
        if (rows[i - windowSize][j] == '#') prevHashes++;
      }
      currentHashes -= prevHashes;
      currentChars -= rows[i - windowSize].length;
    }

    if (i >= windowSize - 1 && currentChars > 0) {
      densities.add(currentHashes.toDouble() / currentChars.toDouble());
    }
  }

  double maxDiff = densities[windowSize] - densities[0];
  double minDensity = densities[0];

  for (int j = windowSize; j < densities.length; j++) {
    if (densities[j - windowSize] < minDensity) {
      minDensity = densities[j - windowSize];
    }
    double diff = densities[j] - minDensity;
    if (diff > maxDiff) {
      maxDiff = diff;
    }
  }

  return maxDiff;
}

