int candidate(List<int> schedule) {
  if (schedule.isEmpty) return 0;

  int maxStreak = 0;
  int currentStreak = 0;

  for (int i = 0; i < schedule.length; i++) {
    int block = schedule[i];

    if (block == -1) {
      currentStreak += 64;
      if (currentStreak > maxStreak) {
        maxStreak = currentStreak;
      }
    } else {
      int leading = countLeadingOnes(block);
      if (currentStreak + leading > maxStreak) {
        maxStreak = currentStreak + leading;
      }

      int internalMax = maxInternalStreak(block);
      if (internalMax > maxStreak) {
        maxStreak = internalMax;
      }

      currentStreak = countTrailingOnes(block);
    }
  }
  return maxStreak;
}

int countTrailingOnes(int x) {
  int count = 0;
  while ((x & 1) == 1 && count < 64) {
    count++;
    x >>= 1;
  }
  return count;
}

int countLeadingOnes(int x) {
  int count = 0;
  while (((x >> 63) & 1) == 1 && count < 64) {
    count++;
    x <<= 1;
  }
  return count;
}

int maxInternalStreak(int x) {
  int maxLen = 0;
  int temp = x;
  while (temp != 0) {
    temp &= (temp << 1);
    maxLen++;
  }
  return maxLen;
}

