  if (signals.isEmpty || topCount <= 0) return 0.0;

  int signalBin(int signal) {
    if (signal >= -50) return 1;
    if (signal >= -60) return 2;
    if (signal >= -70) return 3;
    if (signal >= -80) return 4;
    if (signal >= -90) return 5;
    return 6;
  }

  List<int> sorted = List<int>.from(signals);
  sorted.sort((int a, int b) {
    int binA = signalBin(a);
    int binB = signalBin(b);
    if (binA != binB) return binA.compareTo(binB);
    return b.compareTo(a);
  });

  int count = topCount < sorted.length ? topCount : sorted.length;
  List<int> top = sorted.sublist(0, count);

  int mid = count ~/ 2;
  if (count % 2 == 1) {
    return top[mid].toDouble();
  } else {
    return (top[mid - 1] + top[mid]) / 2.0;
  }
}

