  int byeCount = bracketSize - teamCount;

  int noByePenalty = 0;
  for (int i = 1; i < rounds; i++) {
    int gap = roundDays[i] - roundDays[i - 1];
    if (gap < minimumRestDays) {
      noByePenalty += minimumRestDays - gap;
    }
  }

  int byePenalty = 0;
  if (byeCount > 0 && rounds > 1) {
    for (int i = 2; i < rounds; i++) {
      int gap = roundDays[i] - roundDays[i - 1];
      if (gap < minimumRestDays) {
        byePenalty += minimumRestDays - gap;
      }
    }
  } else {
    byePenalty = noByePenalty;
  }

  return (noByePenalty - byePenalty) / 2.0;
