int candidate(List<String> signals) {
  int transitions(String s) {
    int count = 0;
    for (int i = 1; i < s.length; i++) {
      if (s[i] != s[i - 1]) {
        count++;
      }
    }
    return count;
  }

  int dashCount(String s) {
    int count = 0;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '-') {
        count++;
      }
    }
    return count;
  }

  int customLex(String a, String b) {
    int limit = a.length < b.length ? a.length : b.length;
    for (int i = 0; i < limit; i++) {
      if (a[i] == b[i]) {
        continue;
      }
      if (a[i] == '-') {
        return -1;
      }
      return 1;
    }
    return a.length.compareTo(b.length);
  }

  List<Map<String, Object>> indexed = [];
  for (int i = 0; i < signals.length; i++) {
    indexed.add({'value': signals[i], 'index': i});
  }

  indexed.sort((a, b) {
    String sa = a['value'] as String;
    String sb = b['value'] as String;

    int ta = transitions(sa);
    int tb = transitions(sb);
    if (ta != tb) {
      return ta.compareTo(tb);
    }

    int da = dashCount(sa);
    int db = dashCount(sb);
    if (da != db) {
      return db.compareTo(da);
    }

    if (sa.length != sb.length) {
      return sa.length.compareTo(sb.length);
    }

    int lex = customLex(sa, sb);
    if (lex != 0) {
      return lex;
    }

    return (a['index'] as int).compareTo(b['index'] as int);
  });

  int score = 0;
  for (int sortedIndex = 0; sortedIndex < indexed.length; sortedIndex++) {
    int originalIndex = indexed[sortedIndex]['index'] as int;
    String value = indexed[sortedIndex]['value'] as String;
    score += (originalIndex - sortedIndex).abs() * (transitions(value) + 1);
  }

  return score;
}

