bool candidate(String dna, int windowSize) {
  int bitForBase(String ch) {
    switch (ch) {
      case 'A':
        return 1;
      case 'C':
        return 2;
      case 'G':
        return 4;
      case 'T':
        return 8;
      default:
        return -1;
    }
  }

  final int n = dna.length;
  if (n == 0 || windowSize <= 0 || windowSize > n) {
    return false;
  }

  if (n > 16) {
    return false;
  }

  int parityMask = 0;

  for (int i = 0; i < windowSize; i++) {
    final int bit = bitForBase(dna[i]);
    if (bit == -1) {
      return false;
    }
    parityMask ^= bit;
  }

  int seenMasks = 0;

  for (int start = 0; start < n; start++) {
    final int marker = 1 << parityMask;
    if ((seenMasks & marker) != 0) {
      return false;
    }
    seenMasks |= marker;

    final int outgoingBit = bitForBase(dna[start]);
    final int incomingBit = bitForBase(dna[(start + windowSize) % n]);

    if (outgoingBit == -1 || incomingBit == -1) {
      return false;
    }

    parityMask ^= outgoingBit;
    parityMask ^= incomingBit;
  }

  return true;
}

