  double score = 0.0;

  for (int i = 0; i < departures.length; i++) {
    int current = departures[i] % cycleMinutes;
    int next = departures[(i + 1) % departures.length] % cycleMinutes;

    int gap = next - current;
    if (gap <= 0) {
      gap += cycleMinutes;
    }

    int sharedFactor = gcd(gap, cycleMinutes);

    if (isPrime(sharedFactor)) {
      score += 0.5;
    } else if (sharedFactor == 1) {
      score += 0.25;
    }

    if (isPrime(gap)) {
      score += 0.25;
    }
  }

  return score;
}

