double candidate(List<int> days, List<double> heights, int cycleDays) {
  if (cycleDays <= 0 || days.isEmpty || days.length != heights.length) {
    return 0.0;
  }

  Map<int, double> merged = {};
  for (int i = 0; i < days.length; i++) {
    int day = days[i] % cycleDays;
    if (day < 0) {
      day += cycleDays;
    }

    double height = heights[i];
    if (!merged.containsKey(day) || height > merged[day]!) {
      merged[day] = height;
    }
  }

  List<int> sortedDays = merged.keys.toList()..sort();
  int n = sortedDays.length;
  if (n == 1) {
    return cycleDays + merged[sortedDays[0]]!;
  }

  List<int> gaps = [];
  List<bool> slack = [];
  List<double> lows = [];

  for (int i = 0; i < n; i++) {
    int currentDay = sortedDays[i];
    int nextDay = sortedDays[(i + 1) % n];
    double currentHeight = merged[currentDay]!;
    double nextHeight = merged[sortedDays[(i + 1) % n]]!;

    int gap = nextDay - currentDay;
    if (gap <= 0) {
      gap += cycleDays;
    }

    int diffQuarters = ((nextHeight - currentHeight) * 4).round().abs();
    bool isSlack = diffQuarters <= gap * 2;

    gaps.add(gap);
    slack.add(isSlack);
    lows.add(currentHeight < nextHeight ? currentHeight : nextHeight);
  }

  double best = 0.0;

  for (int start = 0; start < n; start++) {
    if (!slack[start]) {
      continue;
    }

    int totalGap = 0;
    double low = 1000000.0;

    for (int step = 0; step < n; step++) {
      int idx = (start + step) % n;
      if (!slack[idx]) {
        break;
      }

      totalGap += gaps[idx];
      if (lows[idx] < low) {
        low = lows[idx];
      }

      double score = totalGap + low;
      if (score > best) {
        best = score;
      }
    }
  }

  return best;
}

