int candidate(List<String> rows) {
  Set<String> seenPatterns = {};
  int score = 0;

  for (String row in rows) {
    String normalized = '';

    for (int i = 0; i < row.length; i++) {
      if (i == 0 || row[i] != row[i - 1]) {
        normalized += row[i];
      }
    }

    if (seenPatterns.contains(normalized)) {
      continue;
    }
    seenPatterns.add(normalized);

    bool mirrored = true;
    for (int i = 0; i < normalized.length ~/ 2; i++) {
      if (normalized[i] != normalized[normalized.length - 1 - i]) {
        mirrored = false;
        break;
      }
    }

    int filledCount = 0;
    int transitions = 0;

    for (int i = 0; i < row.length; i++) {
      if (row[i] == '#') {
        filledCount++;
      }
      if (i > 0 && row[i] != row[i - 1]) {
        transitions++;
      }
    }

    if (mirrored) {
      score += normalized.length + filledCount;
    } else {
      score += transitions * 2;
    }
  }

  return score;
}

