Set<int> candidate(int rows, int seatsPerRow, int base, int modulus) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }

  int reversedBaseValue(int n, int radix) {
    int value = 0;
    while (n > 0) {
      value = value * radix + (n % radix);
      n ~/= radix;
    }
    return value;
  }

  Set<int> result = <int>{};
  if (rows <= 0 || seatsPerRow <= 0 || base < 2 || modulus < 1) {
    return result;
  }

  int totalSeats = rows * seatsPerRow;

  for (int seat = 1; seat <= totalSeats; seat++) {
    int mirrored = reversedBaseValue(seat, base);
    if (!isPrime(mirrored)) continue;
    if (gcd(seat, modulus) != 1) continue;

    int temp = seat;
    int digitGcd = 0;
    while (temp > 0) {
      int digit = temp % base;
      if (digit != 0) {
        digitGcd = digitGcd == 0 ? digit : gcd(digitGcd, digit);
      }
      temp ~/= base;
    }

    int row = ((seat - 1) ~/ seatsPerRow) + 1;

    if (digitGcd == 1 &&
        (mirrored + row) % modulus == seat % modulus) {
      result.add(seat);
    }
  }

  return result;
}
